import math
def control(obs):
    cam=obs.get('views',{}).get('camera')
    h=obs['hitch_deg']
    if not cam:
        return (h,0,-23)
    th=math.radians(obs['rig']['trailer_heading_deg'])
    c,s=math.cos(th),math.sin(th)
    rear=obs['rig']['trailer_rear']
    origin=cam['origin']
    pts=[]
    for b,d in cam.get('walls',[]):
        b=math.radians(b)
        dx=origin[0]+d*math.cos(b)-rear[0]
        dy=origin[1]+d*math.sin(b)-rear[1]
        u=-(dx*c+dy*s)
        w=-dx*s+dy*c
        if u>0.3: pts.append((u,w))
    centres=[]
    for u in [1.5,2.5,3.5,4.5,5.5]:
        left=[p for p in pts if p[1]>0]
        right=[p for p in pts if p[1]<0]
        if left and right:
            l=min(left,key=lambda p:abs(p[0]-u))
            r=min(right,key=lambda p:abs(p[0]-u))
            if abs(l[0]-u)<1.2 and abs(r[0]-u)<1.2:
                centres.append((u,(l[1]+r[1])/2))
    if not centres:
        wake('Camera cannot resolve the corridor centre')
        return (h,0,-23)
    u,w=min(centres,key=lambda p:abs(p[0]-3.5))
    desired=math.degrees(math.atan2(2*3.2*w,u*u+w*w))
    desired=max(-28,min(28,desired))
    steer=max(-34,min(34,2.6*h-1.85*desired))
    return (steer,-0.85,-23)

